from queueing import payload


def submit(owner, enqueue, batch_size=20):
    if isinstance(batch_size, bool) or not isinstance(batch_size, int) or not 1 <= batch_size <= 100:
        raise ValueError("batch_size must be an integer between 1 and 100")
    return enqueue(payload(owner, batch_size))

from api import submit
from queueing import payload
from worker import execute


def test_submit_default_batch_size():
    received = {}
    def enqueue(p):
        received.update(p)
        return "ok"
    submit("alice", enqueue)
    assert received == {"owner": "alice", "batch_size": 20}


def test_submit_custom_batch_size():
    received = {}
    def enqueue(p):
        received.update(p)
        return "ok"
    submit("bob", enqueue, batch_size=7)
    assert received == {"owner": "bob", "batch_size": 7}


def test_submit_rejects_bool():
    try:
        submit("carol", lambda p: None, batch_size=True)
    except ValueError:
        return
    raise AssertionError("bool batch_size should raise ValueError")


def test_submit_rejects_zero():
    try:
        submit("dave", lambda p: None, batch_size=0)
    except ValueError:
        return
    raise AssertionError("0 batch_size should raise ValueError")


def test_submit_rejects_too_large():
    try:
        submit("erin", lambda p: None, batch_size=101)
    except ValueError:
        return
    raise AssertionError("101 batch_size should raise ValueError")


def test_submit_rejects_non_int():
    try:
        submit("frank", lambda p: None, batch_size="5")
    except ValueError:
        return
    raise AssertionError("string batch_size should raise ValueError")


def test_submit_rejects_before_enqueue():
    calls = []
    def enqueue(p):
        calls.append(p)
        return "ok"
    try:
        submit("grace", enqueue, batch_size=999)
    except ValueError:
        return
    raise AssertionError("invalid batch_size should raise ValueError")
    assert calls == []


def test_worker_uses_batch_size():
    calls = []
    def enqueue(p):
        calls.append(p)
        return "ok"
    submit("henry", enqueue, batch_size=42)
    assert execute(calls[0], lambda o, b: (o, b)) == ("henry", 42)


def test_worker_legacy_payload_defaults_to_20():
    assert execute({"owner": "ivy"}, lambda o, b: (o, b)) == ("ivy", 20)


def test_payload_preserves_owner():
    assert payload("jack", 15)["owner"] == "jack"
    assert payload("jack", 15)["batch_size"] == 15
